INSERT INTO `changelog` (translation_id, old_text, new_text, version_tag)
SELECT (SELECT id FROM quran_translations WHERE surah_number = 18 AND verse_number = 49), translation_text, 'และเมื่อสมุดบันทึกการปฏิบัติถูกวางไว้ บางคนจะหยิบบันทึกของเขาด้วยมือขวาและบางคนจะหยิบด้วยมือซ้าย และพวกเจ้า-โอ้มนุษย์ทั้งหลาย- จะได้เห็นผู้ปฏิเสธศรัทธาอยู่ในสภาพที่กลัวถึงสิ่งที่ถูกบันทึกไว้ในนั้น เพราะพวกเขารู้อยู่แล้วว่าพวกเขาได้ทำอะไรไป คือการปฏิเสธศรัทธาและการเนรคุณต่างๆ พวกเขากล่าวว่า "ความวิบัติของเราช่างน่าสมเพชและยิ่งใหญ่เพียงใด! มันคือบันทึกอะไรกัน มันไม่ทิ้งสักอย่างเลย จะเป็นเรื่องเล็กๆหรือเรื่องใหญ่ๆ แต่ทั้งหมดถูกจัดเก็บและบันทึกไว้หมด" และพวกเขาพบว่าทุกสิ่งที่พวกเขาทำในชีวิตบนโลกนี้ในรูปแบบของการเนรคุณต่างๆได้รับการบันทึกและจัดเก็บ แท้จริง -โอ้รอซูลเอ๋ย - พระผู้อภิบาลของเจ้าไม่ได้อธรรมต่อผู้ใด ดังนั้นพระองค์จะไม่ลงโทษผู้ใดโดยไม่ทำบาปหรือลดรางวัลแห่งความดีงามของผู้ที่เชื่อฟังพระองค์แม้แต่นิดเดียว', 'v2026-11-10-mukhtasar-proofread-2'
FROM verse_translations
WHERE surah_number = 18 AND verse_number = 49 AND source_id IN (SELECT id FROM translation_sources WHERE external_type = 'mokhtasr') AND translation_text = 'และเมื่อสมุดบันทึกการปฏิบัติถูกวางไว้ บางคนจะหยิบบันทึกของเขาด้วยมือขวาและบางคนจะหยิบด้วยมือซ้าย และพวกเจ้า-โอ้มนุษย์ทั้งหลาย- จะได้เห็นผู้ปฏิเสธศรัทธาอยู่ในสภาพที่กลัวถึงสิ่งที่ถูกบันทึกไว้ในนั้น เพราะพวกเขารู้อยู่แล้วว่าพวกเขาได้ทำอะไรไป คือการปฏิเสธศรัทธาและการเนรคุณต่างๆ พวกเขากล่าวว่า "ความวิบัติของเราช่างน่าสมเพชและยิ่งใหญ่เพียงใด! มันคือบันทึกอะไรกัน มันไม่ทิ้งสักอย่างเลย จะเป็นเรื่องเล็กๆหรือเรื่องใหญ่ๆ แต่ทั้งหมดถูกจัดเก็บและบันทึกไว้หมด" และพวกเขาพบว่าทุกสิ่งที่พวกเขาทำในชีวิตบนโลกนี้ในรูปแบบของการเนรคุณต่างๆได้รับการบันทึกและจัดเก็บ แท้จริงพระผู้อภิบาลของเจ้า -โอ้รอซูลเอ๋ย- ไม่ได้อธรรมต่อผู้ใด ดังนั้นพระองค์จะไม่ลงโทษผู้ใดโดยไม่ทำบาปหรือลดรางวัลแห่งความดีงามของผู้ที่เชื่อฟังพระองค์แม้แต่นิดเดียว';
