INSERT INTO `changelog` (translation_id, old_text, new_text, version_tag)
SELECT (SELECT id FROM quran_translations WHERE surah_number = 18 AND verse_number = 82), translation_text, 'ในส่วนเรื่องการซ่อมแซมกำแพงที่ท่านนบีมูซาได้ปฏิเสธนั้น มันเป็นของเด็กผู้ชายกำพร้าสองคนที่อยู่ในเมืองนั้น และพ่อของเขาตายแล้ว และใต้กำแพงนั้นมีขุมทรัพย์ของเขาทั้งสอง และพ่อของเด็กทั้งสองก็เป็นคนดี ดังนั้น พระผู้เป็นเจ้าของท่านทรงประสงค์ที่จะให้เด็กทั้งสองบรรลุสู่ความเป็นผู้ใหญ่ก่อน แล้วจะให้เด็กทั้งสองเอาขุมทรัพย์ของเขาทั้งสองออกมาเอง ถ้าผนังกำแพงนี้ล้มลงก่อนก็จะไม่เป็นการปกปิดทรัพย์สินของเขา เกรงกลัวว่าจะหายไปก่อนที่เขาจะโต และนี้เป็นความเมตตาจากพระผู้เป็นเจ้าของท่านต่อเด็กทั้งสอง และฉันมิได้ทำสิ่งนั้นตามความพอใจของฉัน นั่นคือความหมายที่ท่านไม่สามารถมีความอดทนในสิ่งนั้นๆได้', 'v2026-11-10-mukhtasar-proofread-2'
FROM verse_translations
WHERE surah_number = 18 AND verse_number = 82 AND source_id IN (SELECT id FROM translation_sources WHERE external_type = 'mokhtasr') AND translation_text = 'ในส่วนเรื่องการซ่อมแซมกำแพงที่ท่านนบีมูซาได้ปฏิเสธนั้น มันเป็นของเด็กผู้ชายกำพร้าสองคนที่อยู่ในเมืองนั้น ซึ่งพ่อของเขาตายแล้ว และใต้กำแพงนั้นมีขุมทรัพย์ของเขาทั้งสอง และพ่อของเด็กทั้งสองก็เป็นคนดี ดังนั้น พระผู้เป็นเจ้าของท่านทรงประสงค์ที่จะให้เด็กทั้งสองบรรลุสู่ความเป็นผู้ใหญ่ก่อน แล้วจะให้เด็กทั้งสองเอาขุมทรัพย์ของเขาทั้งสองออกมาเอง ถ้าผนังกำแพงนี้ล้มลงก่อนก็จะไม่เป็นการปกปิดทรัพย์สินของเขา เกรงกลัวว่าจะหายไปก่อนที่เขาจะโต และนี้เป็นความเมตตาจากพระผู้เป็นเจ้าของท่านต่อเด็กทั้งสอง และฉันมิได้ทำสิ่งนั้นตามความพอใจของฉัน นั่นคือความหมายที่ท่านไม่สามารถมีความอดทนในสิ่งนั้นๆได้';
--> statement-breakpoint
UPDATE `verse_translations`
SET translation_text = 'ในส่วนเรื่องการซ่อมแซมกำแพงที่ท่านนบีมูซาได้ปฏิเสธนั้น มันเป็นของเด็กผู้ชายกำพร้าสองคนที่อยู่ในเมืองนั้น และพ่อของเขาตายแล้ว และใต้กำแพงนั้นมีขุมทรัพย์ของเขาทั้งสอง และพ่อของเด็กทั้งสองก็เป็นคนดี ดังนั้น พระผู้เป็นเจ้าของท่านทรงประสงค์ที่จะให้เด็กทั้งสองบรรลุสู่ความเป็นผู้ใหญ่ก่อน แล้วจะให้เด็กทั้งสองเอาขุมทรัพย์ของเขาทั้งสองออกมาเอง ถ้าผนังกำแพงนี้ล้มลงก่อนก็จะไม่เป็นการปกปิดทรัพย์สินของเขา เกรงกลัวว่าจะหายไปก่อนที่เขาจะโต และนี้เป็นความเมตตาจากพระผู้เป็นเจ้าของท่านต่อเด็กทั้งสอง และฉันมิได้ทำสิ่งนั้นตามความพอใจของฉัน นั่นคือความหมายที่ท่านไม่สามารถมีความอดทนในสิ่งนั้นๆได้', last_updated = strftime('%s', 'now'), is_locked = 1
WHERE surah_number = 18 AND verse_number = 82 AND source_id IN (SELECT id FROM translation_sources WHERE external_type = 'mokhtasr') AND translation_text = 'ในส่วนเรื่องการซ่อมแซมกำแพงที่ท่านนบีมูซาได้ปฏิเสธนั้น มันเป็นของเด็กผู้ชายกำพร้าสองคนที่อยู่ในเมืองนั้น ซึ่งพ่อของเขาตายแล้ว และใต้กำแพงนั้นมีขุมทรัพย์ของเขาทั้งสอง และพ่อของเด็กทั้งสองก็เป็นคนดี ดังนั้น พระผู้เป็นเจ้าของท่านทรงประสงค์ที่จะให้เด็กทั้งสองบรรลุสู่ความเป็นผู้ใหญ่ก่อน แล้วจะให้เด็กทั้งสองเอาขุมทรัพย์ของเขาทั้งสองออกมาเอง ถ้าผนังกำแพงนี้ล้มลงก่อนก็จะไม่เป็นการปกปิดทรัพย์สินของเขา เกรงกลัวว่าจะหายไปก่อนที่เขาจะโต และนี้เป็นความเมตตาจากพระผู้เป็นเจ้าของท่านต่อเด็กทั้งสอง และฉันมิได้ทำสิ่งนั้นตามความพอใจของฉัน นั่นคือความหมายที่ท่านไม่สามารถมีความอดทนในสิ่งนั้นๆได้';
